async fn timing(req: Request, next: Next) -> Response {
    let t0 = Instant::now();                       // pre
    let mut res = next.run(req).await;             // inner layers, then the handler
    res.headers_mut().insert(
        header::HeaderName::from_static("x-time"),
        HeaderValue::from_str(&format!("{}us", t0.elapsed().as_micros())).unwrap(),   // post
    );
    res
}
let app = Router::new().route("/", get(handler)).layer(middleware::from_fn(timing));
